**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <queue>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    char tab[6][6];
    for (int i = 0; i < 6; i++)
        for (int j = 0; j < 6; j++)
            plik >> tab[i][j];

    bool visited[6][6] = {};
    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};

    queue<pair<int,int>> q;
    int si = 0, sj = 0;
    q.push({si, sj});
    visited[si][sj] = true;

    int cnt = 0;
    while (!q.empty()) {
        auto [i, j] = q.front(); q.pop();
        tab[i][j] = '*';
        cnt++;
        for (int d = 0; d < 4; d++) {
            int ni = i + dx[d], nj = j + dy[d];
            if (ni >= 0 && ni < 6 && nj >= 0 && nj < 6
                && !visited[ni][nj] && tab[ni][nj] == '.') {
                visited[ni][nj] = true;
                q.push({ni, nj});
            }
        }
    }

    cout << "a) Zamalowane pola: " << cnt << endl;
    cout << "b) Siatka:" << endl;
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            if (j > 0) cout << " ";
            cout << tab[i][j];
        }
        cout << endl;
    }
    return 0;
}
```

**Wyjasnienie**: BFS z pozycji startowej (0,0) przechodzi po wszystkich osiagalnych polach '.'. Kazde odwiedzone pole zamieniamy na '*'.

Weryfikacja:
```
  j: 0 1 2 3 4 5
i=0: . . # . . .
i=1: . . # . . .
i=2: # # # . . .
i=3: . . . . . .
i=4: . . . # # #
i=5: . . . # . .
```
Start (0,0)='.':
BFS kolejka: (0,0)
- (0,0): sasiedzi: gora=brak, dol=(1,0)='.', lewo=brak, prawo=(0,1)='.'
  Dodaj: (1,0), (0,1)
- (1,0): sasiedzi: gora=(0,0)vis, dol=(2,0)='#', lewo=brak, prawo=(1,1)='.'
  Dodaj: (1,1)
- (0,1): sasiedzi: gora=brak, dol=(1,1)(juz dodano), lewo=(0,0)vis, prawo=(0,2)='#'
  Nic nowego
- (1,1): sasiedzi: gora=(0,1)vis, dol=(2,1)='#', lewo=(1,0)vis, prawo=(1,2)='#'
  Nic nowego

Zamalowane: (0,0), (1,0), (0,1), (1,1) = 4 pola.
Lewy gorny prostokat 2x2 odciety scianami '#'.
